void kyogreMoveDemo::Init(){work=0;work=new MoveWork;memset(work,0,0x3C);effect=0;effect=new glowEffect;work->type=_movdemo_type;soundStopEnv(1000);if(work->type==0)playBGM(0x53D);GSsndPlayNow(0x5B8);work->body=0x1B870400;work->bodyModel=0x1B871000;work->group=floorGetCurrentGroupID();GSgfxVideoSetLockFrameRate(true);switch(work->type){case 1:work->mount=0x21200400;work->mountModel=0x21201000;work->part=1;work->cameraID=0x211E1800;break;case 0:work->mount=0x21210400;work->mountModel=0x21211000;work->part=1;work->cameraID=0x211F1800;break;}if(effect){effect->strength=_glowstrngth;effect->width=_glowwidth;effect->blend=_glowblend;effect->normalize=_glownormalize;effect->method=_glowmethod;effect->samples=_glowsamples;effect->Start();}SetModel(work->group,work->mount,false);GSmodelSetBoundCheck(GSresGetResourceAllGroup(work->mountModel),false);SetModel(work->group,0x21AC0400,false);GSmodelSetBoundCheck(GSresGetResourceAllGroup(0x21AC1000),false);SetMotion(0x21AC1000,8,0.0f,true);SetModel(work->group,work->body,false);GSmodelSetBoundCheck(GSresGetResourceAllGroup(work->bodyModel),false);ModelAttach(work->bodyModel,work->mountModel,work->part,(GSattachMode)7);SetMotion(work->bodyModel,8,0.0f,true);ModelAttach(0x21AC1000,0x1B871000,1,(GSattachMode)4);switch(work->type){case 1:work->particles[0]=SetModelPartPaticle(work->bodyModel,0x21391400,5,(GSattachMode)1,false,true,false);work->particles[1]=SetModelPartPaticle(work->bodyModel,0x213A1400,0x13,(GSattachMode)1,false,true,false);work->particles[2]=SetModelPartPaticle(work->bodyModel,0x213B1400,0x1A,(GSattachMode)1,false,true,false);work->particles[3]=SetModelPartPaticle(work->bodyModel,0x213C1400,0xC,(GSattachMode)1,false,true,false);break;case 0:work->particles[0]=SetModelPartPaticle(work->bodyModel,0x21DE1400,5,(GSattachMode)1,false,true,false);work->particles[1]=SetModelPartPaticle(work->bodyModel,0x21DF1400,0x13,(GSattachMode)1,false,true,false);work->particles[2]=SetModelPartPaticle(work->bodyModel,0x213B1400,0x1A,(GSattachMode)1,false,true,false);work->particles[3]=SetModelPartPaticle(work->bodyModel,0x213C1400,0xC,(GSattachMode)1,false,true,false);break;}SetMotion(work->mountModel,0,0.0f,_AnimeLoop);work->frames=GetAnimeFrameCount(work->mountModel,0);work->camera=cameraPlay(work->cameraID,0,_AnimeLoop);f32 fov,aspect,near,far;GScameraGetPerspective(work->camera,&fov,&aspect,&near,&far);far=50000.0f;GScameraSetPerspective(work->camera,fov,aspect,near,50000.0f);}
